# f10 二大陸と内海 - 陸・海・空を全部使う決戦マップ（60x42）。
#
# 中央に内海があり、東西に大陸が分かれている。ただし**南北は陸続き**なので、
# 陸路（南北の回廊）・海路（内海）・空路の3つが同時に開いている。
#   陸: 南北の陸路を山で1か所ずつに絞ってある。ここを抜けば直接殴り合える。
#   海: 内海の島に中立の泊地と野戦飛行場があり、取れば前進基地になる。
#   空: 島の飛行場を押さえないと、中央上空まで往復するだけで燃料が尽きる。
#
# 初期配置は片側26部隊（陸18・海5・空3）。生産も含めるとかなりの数になるので、
# CPUの手番はそれなりに待つ。
#
# 180度回転対称。odd-rヘクスでは左右反転が距離を保たない（約39%の組で変わる）
# ため、対になる図形を回転で置いている。
[map]
name             = 二大陸と内海
width            = 60
height           = 42
turns            = 100
timeout_winner   = -1
funds0           = 5000
funds1           = 5000

